func resolveItem(q: ArrayStack<Int64>, t: Int64): Int64 {
    if (t <= 0) { return 0 }
    var sum: Int64 = 0
    var count: Int64 = 0
    while (count < t) {
        match (q.remove()) {
            case Some(v) =>
                sum += v
                count += 1
            case None =>
                break
        }
    }
    return sum
}

